        else isCellRef = false;

        if (/[0-9.]/.test(c) || (isNumber && /[eE+-/*()]/.test(c))) {
            currentToken += c;
            isNumber = true;
        } else {
            if (currentToken.length > 0) tokens.push(currentToken);

            if (/[A-J][1-9]/.test(c)) { // Cell ref starting like A, then digit(s)
