                while(j < expr.length && /[1-90]/.test(expr[j])) j++;
                currentToken = expr.substring(i, j);
                tokens.push(currentToken);
                i = j - 1;
            } else {
                const opMatch = c.match(/[+\-*/()]/);
                if (opMatch) tokens.push(c);
            }

            currentToken = '';
        }
    }

    if (currentToken.length > 0) tokens.push(currentToken);
    return tokens;
}

